-- 2. Cleaner rate and fees
insert into cleaner_rate_schedule (property_id, effective_from, regular_rate, general_rate, note) values ('6ae230f4-c189-4547-84b1-cb6e0b2cc9bd', '2026-05-07', 650, 1000, '2026-09-14 backfill: Honey charges PHP 650 per clean (her 2026-09-13 message: Sep 7 Aya 650, Sep 13 Dale 650). Start date assumed = Honey tenure start; general rate unchanged.');
create temp table fee_plan on commit drop as
with s as (
  select id, cleaner_name, cleaning_type, created_at, coalesce(checkout_date, checkin_date, (cleaned_at at time zone 'Asia/Manila')::date) as sdate,
         case when cleaning_type = 'turnover' then coalesce(checkout_date, checkin_date, (cleaned_at at time zone 'Asia/Manila')::date) else (cleaned_at at time zone 'Asia/Manila')::date end as dedupe_key,
         lower(coalesce(last_guest_name, '')) = 'test' as is_test
  from cleaning_sessions where property_id = '6ae230f4-c189-4547-84b1-cb6e0b2cc9bd' and fee_paid_at is null and cleaned_at < '2026-09-14'
), r as (
  select s.*, row_number() over (partition by cleaning_type, dedupe_key order by created_at) as rn from s
)
select r.*, case when is_test or rn > 1 then 0 else (select case when r.cleaning_type = 'deep_clean' then c.general_rate else c.regular_rate end from cleaner_rate_schedule c where c.effective_from <= r.sdate order by c.effective_from desc limit 1) end as fee
from r;
insert into transactions (property_id, txn_type, category, status, source, gross_amount, payee_name, transaction_date, external_ref, notes, logged_by)
select '6ae230f4-c189-4547-84b1-cb6e0b2cc9bd', 'expense', 'cleaning', 'confirmed', 'cleaner_fee', fee, cleaner_name, sdate, 'cleanfee:' || id,
       'Cleaning fee - ' || coalesce(cleaner_name, 'cleaner') || ', ' || sdate || ', ' || case when cleaning_type = 'deep_clean' then 'Deep Clean' when cleaning_type = 'mid_stay' then 'Mid-stay' else 'Turnover' end || '. Session ' || left(id::text, 8) || '. Backfill 2026-09-14: paid per Lloyd (all cleans settled up to Dale, 13 Sep).',
       'claude-backfill-2026-09-14'
from fee_plan p where fee > 0 and not exists (select 1 from transactions t where t.external_ref = 'cleanfee:' || p.id);
update cleaning_sessions c set fee_amount = p.fee, fee_paid_at = now(), fee_txn_id = t.id,
  notes = case when p.fee = 0 then concat_ws(' | ', nullif(c.notes, ''), case when p.is_test then 'Backfill 2026-09-14: test submission, no fee' else 'Backfill 2026-09-14: duplicate submission of the same clean, no fee' end) else c.notes end
from fee_plan p left join transactions t on t.external_ref = 'cleanfee:' || p.id
where c.id = p.id and c.fee_paid_at is null;

