-- 4. Reconcile reservations from the new CSV rows and report
select public.reconcile_all_completed_reservations() as reconciled;
select 'csv_rows' as k, count(*)::text as v from airbnb_transactions where source_file = 'airbnb_.csv 2026-09-14'
union all select 'fees_booked', count(*)::text || ' = PHP ' || coalesce(sum(gross_amount), 0)::text from transactions where external_ref like 'cleanfee:%' and logged_by = 'claude-backfill-2026-09-14'
union all select 'sessions_zero_fee', count(*)::text from cleaning_sessions where fee_amount = 0 and notes like '%Backfill 2026-09-14%'
union all select 'unpaid_left', count(*)::text from cleaning_sessions where fee_paid_at is null and cleaned_at < '2026-09-14'
union all select 'expenses_added', count(*)::text || ' = PHP ' || coalesce(sum(gross_amount), 0)::text from transactions where external_ref like 'backfill-2026-09-14:%';
